'use strict';
const $=id=>document.getElementById(id),cv=$('game'),ctx=cv.getContext('2d'),W=1120,H=600;
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x)),rnd=(a,b)=>a+Math.random()*(b-a),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
const blocks=[{x:235,y:150,w:100,h:65},{x:785,y:385,w:100,h:65},{x:235,y:385,w:100,h:65},{x:785,y:150,w:100,h:65},{x:504,y:263,w:112,h:74}];
let mode='cpu',state='menu',players=[],bullets=[],particles=[],pickups=[],rings=[],wells=[],scores=[0,0],roundNo=0,time=90,elapsed=0,last=0;
let keys={},mouse={x:800,y:300,down:false},sound=false,audio,shake=0,toastTime=0,choices=[],draftTurn=0,selectedChars=[0,3],charTurn=0;
let weaponEffects=[];
const effectSprite=new Image();effectSprite.src='assets/weapon-effects.png';
function weaponEffect(row,x,y,angle=0){const duration=[.22,.32,.2,.26][row];weaponEffects.push({row,x,y,angle,age:0,duration,size:[58,94,54,62][row]});if(weaponEffects.length>40)weaponEffects.shift()}
let delayedShots=[],shopTurn=0,shopOffers=[],shopBought=[[],[]],shopReady=[false,false],credits=[100,100];
let supplyTimer=12,relicTimer=17,legendarySpawned=false,legendaryWarned=false,hudTick=0,bookPaused=false,volleyCounter=0;
const sprite=new Image();sprite.src='assets/fighters.png';
const spriteRects=Array.from({length:8},(_,i)=>[(i%4)*384,Math.floor(i/4)*512,384,512]);
const weaponSprite=new Image();weaponSprite.src='assets/weapons.png';
const extraWeaponSprite=new Image();extraWeaponSprite.src='assets/weapons-extra.png';
function weaponAtlas(id){return {image:id<16?weaponSprite:extraWeaponSprite,grid:id<16?4:2,index:id<16?id:id-16}}
function weaponArt(id){return `<span class="weaponart w${id}" role="img" aria-label="${guns[id].name}"></span>`}
function tone(f,d=.06,t='triangle',vol=.025){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=t;o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(f*.45,audio.currentTime+d);g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+d)}catch{}}
let noiseBuffer,masterBus;
function combatSound(kind,id=0){if(!sound)return;try{
 audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();
 if(!masterBus){masterBus=audio.createDynamicsCompressor();masterBus.threshold.value=-18;masterBus.ratio.value=5;masterBus.connect(audio.destination)}
 if(!noiseBuffer){noiseBuffer=audio.createBuffer(1,audio.sampleRate,audio.sampleRate);const d=noiseBuffer.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1}
 const t=audio.currentTime,g=guns[id],energy=g.rail||g.gravity||g.prism,heavy=g.comet||g.type==='SHOTGUN';
 const dur=kind==='boom'?.4:kind==='shot'?(heavy?.2:energy?.16:.09):kind==='reload'?.1:.12;
 const src=audio.createBufferSource(),filter=audio.createBiquadFilter(),gain=audio.createGain();src.buffer=noiseBuffer;filter.type=energy&&kind==='shot'?'bandpass':'lowpass';filter.frequency.setValueAtTime(kind==='reload'?3600:kind==='boom'?650:heavy?1800:energy?4500:2700,t);filter.frequency.exponentialRampToValueAtTime(200,t+dur);
 gain.gain.setValueAtTime(kind==='boom'?.22:kind==='shot'?.12:.065,t);gain.gain.exponentialRampToValueAtTime(.001,t+dur);src.connect(filter);filter.connect(gain);gain.connect(masterBus);src.start(t);src.stop(t+dur);src.onended=()=>{src.disconnect();filter.disconnect();gain.disconnect()};
 const o=audio.createOscillator(),v=audio.createGain();o.type=energy&&kind==='shot'?'sawtooth':'triangle';o.frequency.setValueAtTime(kind==='boom'?90:kind==='reload'?220:energy?1100:heavy?150:240,t);o.frequency.exponentialRampToValueAtTime(kind==='boom'?25:energy?130:45,t+dur);v.gain.setValueAtTime(.07,t);v.gain.exponentialRampToValueAtTime(.001,t+dur);o.connect(v);v.connect(masterBus);o.start(t);o.stop(t+dur);o.onended=()=>{o.disconnect();v.disconnect()};
}catch{}}
function clearInput(){keys={};mouse.down=false}
function toast(t){$('toast').textContent=t;toastTime=3;$('toast').style.opacity=1}
function burst(x,y,color,n=12){for(let i=0;i<n;i++){const a=rnd(0,Math.PI*2),v=rnd(30,180);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rnd(.2,.7),color,size:rnd(2,5)})}if(particles.length>650)particles.splice(0,particles.length-650)}
function pulse(x,y,color,max=100){rings.push({x,y,color,r:5,life:.45,duration:.45,speed:max/.45})}
function overlay(html){$('overlay').innerHTML=html;$('overlay').style.display='flex';clearInput()}
function hideOverlay(){$('overlay').style.display='none';clearInput()}
function makeWeapon(id){const g=guns[id];return{id,clip:g.mag,reserve:g.stock,mode:0}}
function weapon(p){return p.inventory[p.active]}
function hasRelic(p,key){return p.relics.some(i=>relics[i].key===key)}
function makePlayer(id){return {id,char:selectedChars[id],x:id?950:170,y:300,hp:characters[selectedChars[id]].hp,maxHp:characters[selectedChars[id]].hp,r:14,color:id?'#64b5ee':'#f39545',angle:id?Math.PI:0,inventory:[makeWeapon(0)],active:0,relics:[],shot:0,reload:0,reloadSlot:-1,dodge:0,roll:0,dx:id?-1:1,dy:0,inv:0,blanks:characters[selectedChars[id]].blanks,shield:0,melee:0,slash:0,slashAngle:0,recoil:0,muzzle:0,holster:0,ai:rnd(.25,.6),moving:false,walk:0,emptyNotice:0,lastVolley:null,blockedVolley:null}}
function equipSlot(p,index){if(index<0||index>=p.inventory.length||index===p.active)return;if(hasRelic(p,'holster')&&p.holster<=0){const old=weapon(p);if(old.reserve>0&&old.clip<guns[old.id].mag){old.clip++;old.reserve--;p.holster=1.5}}p.active=index;p.reload=0;p.reloadSlot=-1;p.shot=Math.max(p.shot,.15);tone(200);updateHUD()}
function switchGun(p,dir=1){equipSlot(p,(p.active+dir+p.inventory.length)%p.inventory.length)}
function addGun(p,id,replace=false){const owned=p.inventory.find(w=>w.id===id);if(owned){owned.reserve=Math.min(guns[id].stock,owned.reserve+Math.ceil(guns[id].stock*.6));return '弾薬を補給'}if(p.inventory.length<4){p.inventory.push(makeWeapon(id));equipSlot(p,p.inventory.length-1);return '装備に追加'}if(replace){p.inventory[p.active]=makeWeapon(id);p.reload=0;p.reloadSlot=-1;return '装備中の武器と交換'}return false}
function reload(p){const w=weapon(p),g=guns[w.id];if(p.reload||w.clip>=g.mag||w.reserve<=0)return;p.reload=1.15*characters[p.char].reload*(hasRelic(p,'ribbon')?.65:1);p.reloadSlot=p.active;combatSound('reload')}
function finishReload(p){if(p.reloadSlot!==p.active)return;const w=weapon(p),amount=Math.min(guns[w.id].mag-w.clip,w.reserve);w.clip+=amount;w.reserve-=amount;if(amount>0&&guns[w.id].switcher)w.mode=1-w.mode;p.reloadSlot=-1;combatSound('reload')}
function roll(p){if(p.dodge>0)return;p.lastVolley=null;p.roll=.26;p.dodge=characters[p.char].dodge;p.inv=Math.max(p.inv,.31);combatSound('dodge');burst(p.x,p.y,p.color,8);if(hasRelic(p,'comet'))for(let i=0;i<6;i++)spawnBullet(p,i*Math.PI/3,{gun:0,speed:250,damage:.35,life:1.2,r:4,color:'#ecc5ff',shape:'star',canLens:false})}
function blank(p){if(p.blanks<=0)return;p.lastVolley=null;p.blanks--;delayedShots=delayedShots.filter(s=>s.owner===p.id);if(hasRelic(p,'relay'))for(let i=0;i<6;i++)spawnBullet(p,i*Math.PI/3,{gun:0,speed:200,damage:.35,life:1.2,shard:true,canLens:false});bullets=bullets.filter(b=>b.owner===p.id);wells=wells.filter(w=>w.owner===p.id);pulse(p.x,p.y,p.color,900);p.inv=Math.max(p.inv,.65);shake=5;combatSound('boom');toast(`P${p.id+1}：パルス！ 敵弾と重力渦を消去`)}
function inSlash(p,target){const a=Math.atan2(target.y-p.y,target.x-p.x)-p.angle;return dist(p,target)<=64&&Math.cos(a)>=Math.cos(Math.PI/3)&&!lineBlocked(p,target)}
function melee(p){if(p.melee>0||p.roll>0||p.reload>0)return;p.melee=1.1;p.shot=Math.max(p.shot,.3);p.slash=.16;p.slashAngle=p.angle;
 const targets=bullets.filter(b=>!b.dead&&b.owner!==p.id&&inSlash(p,b)).sort((a,b)=>dist(p,a)-dist(p,b)).slice(0,3);
 if(targets.length&&hasRelic(p,'dynamo'))p.dodge=Math.max(0,p.dodge-.3);for(const b of targets){b.dead=true;burst(b.x,b.y,b.color,6)}bullets=bullets.filter(b=>!b.dead);
 const enemy=players[1-p.id];if(inSlash(p,enemy))damage(enemy,.6);combatSound('slash');
}
function spawnBullet(p,a,opts={}){const gun=opts.gun??weapon(p).id,g=guns[gun],special=g.split||g.comet||g.gravity||g.boomerang||g.seed||g.bubble||g.clover;
 const speed=(opts.speed??g.speed)*(hasRelic(p,'heavy')?.8:1);
 bullets.push({x:opts.x??p.x+Math.cos(a)*24,y:opts.y??p.y+Math.sin(a)*24,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,owner:p.id,gun,life:opts.life??(g.seed?3.6:g.bubble?2.8:g.clover?.8:g.split?.68:g.boomerang?1.8:g.comet?1.45:g.gravity?1.05:2.8),age:0,r:opts.r??(g.comet?11:g.gravity?10:g.boomerang?8:g.rail?4:5),color:opts.color??g.color,damage:(opts.damage??g.damage)*(hasRelic(p,'heavy')?1.15:1),parcel:!!opts.parcel,speedScale:hasRelic(p,'heavy')?.8:1,rebounds:0,bounce:opts.bounce??((g.bounce||0)+(!special&&opts.canLens!==false&&hasRelic(p,'lens')?1:0)),phase:opts.phase??1,hit:new Set(),shape:opts.shape??(g.comet?'star':g.prism?'diamond':g.boomerang?'moon':'orb'),shard:!!opts.shard,volley:opts.volley??null,dead:false});}
function fire(p){if(p.shot>0||p.reload||p.roll>0)return;const w=weapon(p),g=guns[w.id];if(w.clip<=0){if(w.reserve>0)reload(p);else if(p.id===0&&p.emptyNotice<=0){toast('弾切れ！ E / 1〜4 で武器切替、弾薬箱で補給。V で近接攻撃');p.emptyNotice=3}return}const first=w.clip===g.mag,scatter=g.switcher&&w.mode===1;p.shot=g.rate;p.recoil=1;p.muzzle=.075;w.clip--;const volley=++volleyCounter,n=scatter?3:g.count||1,colors=['#ff9bbd','#ffe99b','#98efd0','#a4d9ff','#dfafff'];
 const shotDamage=(scatter?.5:g.damage)*(first&&hasRelic(p,'starter')?1.2:1);
 for(let i=0;i<n;i++){const a=g.radial?p.angle+i*Math.PI*2/n:p.angle+(i-(n-1)/2)*(scatter?.16:g.spread||.11);spawnBullet(p,a,{volley,damage:shotDamage,parcel:g.parcel&&w.clip===0,r:g.parcel&&w.clip===0?9:undefined,phase:i%2?1:-1,color:g.prism?colors[i%5]:g.color})}
 if(g.echo)delayedShots.push({owner:p.id,gun:w.id,angle:p.angle,damage:shotDamage,delay:.24,volley});
 burst(p.x+Math.cos(p.angle)*26,p.y+Math.sin(p.angle)*26,g.color,g.prism?12:4);if(g.comet||g.prism)shake=3;combatSound('shot',w.id)}
function circleRect(x,y,r,b){return Math.hypot(x-clamp(x,b.x,b.x+b.w),y-clamp(y,b.y,b.y+b.h))<r}
// Keep the whole sprite inside the floor; recover invalid/overlapping positions before moving.
const movementBounds={left:60,right:W-60,top:82,bottom:H-60};
function recoverPosition(p){const m=movementBounds;p.x=clamp(Number.isFinite(p.x)?p.x:W/2,m.left,m.right);p.y=clamp(Number.isFinite(p.y)?p.y:H/2,m.top,m.bottom);
 for(let pass=0;pass<blocks.length;pass++){const b=blocks.find(b=>circleRect(p.x,p.y,p.r,b));if(!b)break;
 const candidates=[{x:b.x-p.r-1,y:p.y},{x:b.x+b.w+p.r+1,y:p.y},{x:p.x,y:b.y-p.r-1},{x:p.x,y:b.y+b.h+p.r+1}].filter(c=>c.x>=m.left&&c.x<=m.right&&c.y>=m.top&&c.y<=m.bottom&&!blocks.some(b=>circleRect(c.x,c.y,p.r,b))).sort((a,b)=>dist(a,p)-dist(b,p));if(candidates[0]){p.x=candidates[0].x;p.y=candidates[0].y}}
}
function move(p,dx,dy,dt){recoverPosition(p);const m=movementBounds,n=Math.max(1,Math.ceil(Math.hypot(dx,dy)*dt/5)),step=dt/n;
 for(let i=0;i<n;i++){const x=clamp(p.x+dx*step,m.left,m.right);if(!blocks.some(b=>circleRect(x,p.y,p.r,b)))p.x=x;const y=clamp(p.y+dy*step,m.top,m.bottom);if(!blocks.some(b=>circleRect(p.x,y,p.r,b)))p.y=y}}
function lineBlocked(a,b){const len=dist(a,b),steps=Math.ceil(len/8);for(let i=1;i<steps;i++){const t=i/steps;if(blocks.some(r=>circleRect(a.x+(b.x-a.x)*t,a.y+(b.y-a.y)*t,2,r)))return true}return false}
function damage(p,n,hazard=false,volley=null){if(p.hp<=0||(volley!==null&&p.blockedVolley===volley)||(p.inv>0&&(volley===null||p.lastVolley!==volley)))return false;if(!hazard&&hasRelic(p,'bell')&&p.shield<=0){p.blockedVolley=volley;p.lastVolley=null;p.shield=12;p.inv=.3;pulse(p.x,p.y,'#ffe2a0',65);tone(700,.14);return false}p.lastVolley=volley;p.hp=Math.max(0,p.hp-n);p.inv=.22;burst(p.x,p.y,p.color,14);shake=4;combatSound('hit');return true}
function addRelic(p,id){if(p.relics.includes(id)||p.relics.length>=3)return false;p.relics.push(id);if(relics[id].key==='heart'){p.maxHp+=2;p.hp=Math.min(p.maxHp,p.hp+2)}pulse(p.x,p.y,relics[id].color,70);return true}
function acquire(p,item,replace=false){if(item.used||item.age<.6)return false;let msg='';if(item.kind==='weapon'){const result=addGun(p,item.gun,replace);if(!result)return false;msg=guns[item.gun].name+'：'+result}else if(item.kind==='relic'){if(!addRelic(p,item.relic))return false;msg=relics[item.relic].name+' を装備'}else{let gained=0;for(const w of p.inventory){const g=guns[w.id],n=Math.min(g.stock-w.reserve,Math.ceil(g.stock*.4));w.reserve+=n;gained+=n}if(!gained)return false;msg='全武器の予備弾を補給'}item.used=true;burst(item.x,item.y,item.kind==='weapon'?RARITIES[guns[item.gun].rarity].color:item.kind==='relic'?relics[item.relic].color:'#a5e9ee',22);tone(640,.18);toast(`P${p.id+1}：${msg}`);updateHUD();return true}
function interact(p){const item=pickups.filter(i=>!i.used&&dist(i,p)<65).sort((a,b)=>dist(a,p)-dist(b,p))[0];if(item)acquire(p,item,true)}
function weightedGun(){const n=Math.random(),r=n<.48?'C':n<.78?'B':n<.95?'A':'S';const ids=guns.map((g,i)=>g.rarity===r?i:-1).filter(i=>i>=0);return ids[Math.floor(Math.random()*ids.length)]}
function putItem(item){if(pickups.some(i=>!i.used&&dist(i,item)<35))return;pickups.push({...item,age:0})}
function spawnSupply(){const gun=weightedGun();for(const s of [{x:160,y:140},{x:960,y:460}])putItem({...s,kind:'weapon',gun});for(const s of [{x:160,y:460},{x:960,y:140}])putItem({...s,kind:'ammo'});toast('武器補給！ 同じ武器と弾薬箱が両サイドに出現')}
function spawnRelics(){const id=Math.floor(Math.random()*relics.length);putItem({x:430,y:150,kind:'relic',relic:id});putItem({x:690,y:450,kind:'relic',relic:id});toast('レリック出現！ 触れて入手・最大3個')}
function showMenu(){state='menu';players=[];time=90;elapsed=0;roundNo=0;scores=[0,0];bullets=[];pickups=[];wells=[];overlay(`<div class="startpanel"><div class="eyebrow">ARENA DUEL</div><div class="party">${characters.map((c,i)=>`<span class="portrait c${i}" role="img" aria-label="${c.name}"></span>`).join('')}</div><h2>CHAMBER <em>CLASH</em></h2><p>武器を選び、アリーナへ。<br>回避・近接・パルスで弾幕を突破しよう。</p><button class="primary" id="start">ファイターを選ぶ <span>✦</span></button><p class="fine">8キャラクター · 20武器 · 12レリック · 3本先取</p></div>`);$('start').onclick=showCharacters;updateHUD()}
function showCharacters(){charTurn=0;renderCharacters()}
function renderCharacters(){state='characters';overlay(`<div class="draft"><div class="eyebrow">CHOOSE YOUR LITTLE HERO</div><h2>P${charTurn+1}：ファイター選択</h2><p>耐久・速度・装填・回避の得意分野で選ぼう。</p><div class="choices characters">${characters.map((c,i)=>`<button class="weaponcard character" data-character="${i}" style="--rarity:${c.color}"><span class="portrait c${i}" role="img" aria-label="${c.name}"></span><h3>${c.name}</h3><small>${c.role}</small><p>${c.note}</p></button>`).join('')}</div><p>${mode==='local'?'P1 → P2 の順に選択。同じキャラクターも選べます。':'CPUのファイターはランダムで登場します。'}</p></div>`);$('overlay').querySelectorAll('[data-character]').forEach(b=>b.onclick=()=>selectCharacter(+b.dataset.character))}
function selectCharacter(i){selectedChars[charTurn]=i;if(mode==='local'&&charTurn===0){charTurn=1;renderCharacters();return}if(mode==='cpu'){const pool=characters.map((_,n)=>n).filter(n=>n!==i);selectedChars[1]=pool[Math.floor(Math.random()*pool.length)]}startMatch()}
function startMatch(){scores=[0,0];roundNo=0;credits=[100,100];nextRound()}
function nextRound(){roundNo++;weaponEffects=[];delayedShots=[];shopBought=[[],[]];shopReady=[false,false];credits=scores.map((n,i)=>100+Math.min(30,Math.max(0,scores[1-i]-n)*15));players=[makePlayer(0),makePlayer(1)];bullets=[];particles=[];rings=[];wells=[];pickups=[];time=90;elapsed=0;supplyTimer=12;relicTimer=17;legendarySpawned=false;legendaryWarned=false;
 const rare=guns.map((g,i)=>g.rarity==='B'?i:-1).filter(i=>i>=0).sort(()=>Math.random()-.5),epic=guns.map((g,i)=>g.rarity==='A'?i:-1).filter(i=>i>=0);choices=[rare[0],rare[1],epic[Math.floor(Math.random()*epic.length)]];draftTurn=0;showDraft();updateHUD()}
function gunCard(id){const g=guns[id],r=RARITIES[g.rarity];return `${weaponArt(id)}<small>${g.rarity} / ${r.name}</small><h3>${g.name}</h3><p>${g.desc}</p><div class="stats">装填 ${g.mag} / 予備 ${g.stock}</div>`}
function showDraft(){state='draft';overlay(`<div class="draft"><div class="eyebrow">ROUND ${roundNo} · WEAPON SELECT</div><h2>P${draftTurn+1}：初期武器を選択</h2><p>両者に同じ3候補。無料の初期武器を選んだ後、ショップへ。</p><div class="choices">${choices.map(n=>`<button class="weaponcard" data-gun="${n}" style="--rarity:${RARITIES[guns[n].rarity].color}">${gunCard(n)}</button>`).join('')}</div><p>拾った武器は4丁まで保持。レリックは3個まで。全武器に有限の予備弾。</p><p class="hintline">30秒で中央にSレア武器が出現。取りに行く？ 待ち伏せする？</p></div>`);$('overlay').querySelectorAll('[data-gun]').forEach(b=>b.onclick=()=>selectGun(+b.dataset.gun))}
function selectGun(g){addGun(players[draftTurn],g);if(mode==='local'&&draftTurn===0){draftTurn=1;showDraft();return}if(mode==='cpu')addGun(players[1],choices[Math.floor(Math.random()*choices.length)]);openShop()}
function launchRound(){state='play';hideOverlay();const initial=weightedGun();putItem({x:560,y:125,kind:'weapon',gun:initial});putItem({x:560,y:475,kind:'weapon',gun:initial});putItem({x:160,y:460,kind:'ammo'});putItem({x:960,y:140,kind:'ammo'});putItem({x:430,y:150,kind:'relic',relic:0});putItem({x:690,y:450,kind:'relic',relic:0});toast('FIGHT! 装備に触れて入手。E / 1〜4 で武器切替');tone(530,.18);updateHUD()}
function aiInput(p,dt){const enemy=players[0],d=dist(p,enemy);p.angle=Math.atan2(enemy.y-p.y,enemy.x-p.x)+Math.sin(elapsed*2.2)*.09;const w=weapon(p);if(w.clip+w.reserve===0){const index=p.inventory.findIndex(x=>x.clip+x.reserve>0);if(index>=0)equipSlot(p,index)}
 let target=null,best=Infinity;for(const item of pickups){let desired=item.kind==='ammo'?p.inventory.some(x=>x.reserve<guns[x.id].stock*.6):item.kind==='relic'?p.relics.length<3&&!p.relics.includes(item.relic):p.inventory.length<4||p.inventory.some(x=>x.id===item.gun&&x.reserve<guns[x.id].stock*.6)||guns[item.gun].rarity==='S';if(!desired)continue;const cost=dist(p,item)*(item.kind==='weapon'&&guns[item.gun].rarity==='S'?.65:1);if(cost<best){best=cost;target=item}}
 let a=Math.atan2(enemy.y-p.y,enemy.x-p.x),forward=d>340?1:d<200?-1:0,dx=Math.cos(a)*forward+Math.cos(a+Math.PI/2)*Math.sin(elapsed*.7)*.8,dy=Math.sin(a)*forward+Math.sin(a+Math.PI/2)*Math.sin(elapsed*.7)*.8;
 if(target&&best<500){a=Math.atan2(target.y-p.y,target.x-p.x);dx=Math.cos(a);dy=Math.sin(a);if(dist(target,p)<45)acquire(p,target,p.inventory.length>=4&&target.kind==='weapon'&&guns[target.gun].rarity==='S')}
 const inset=arenaInset();if(inset&&(p.x<inset+65||p.x>W-inset-65||p.y<inset*.58+60||p.y>H-inset*.58-60)){a=Math.atan2(H/2-p.y,W/2-p.x);dx=Math.cos(a);dy=Math.sin(a)}
 const threat=bullets.find(b=>b.owner!==p.id&&dist(b,p)<90);if(threat){dx+=-(threat.y-p.y)/65;dy+=(threat.x-p.x)/65;p.ai-=dt;if(p.ai<0){roll(p);p.ai=rnd(.35,.75)}}if(p.blanks&&bullets.filter(b=>b.owner===0&&dist(b,p)<120).length>5)blank(p);
 if(blocks.some(b=>circleRect(p.x+dx*40,p.y+dy*40,18,b))){let base=Math.atan2(dy,dx);for(const turn of [Math.PI/2,-Math.PI/2,Math.PI]){const tx=Math.cos(base+turn),ty=Math.sin(base+turn);if(!blocks.some(b=>circleRect(p.x+tx*45,p.y+ty*45,18,b))){dx=tx;dy=ty;break}}}
 if(weapon(p).clip===0)reload(p);if(d<64)melee(p);return {dx,dy,shoot:!lineBlocked(p,enemy)||guns[weapon(p).id].bounce>0||guns[weapon(p).id].boomerang}}
function arenaInset(){return elapsed>60?Math.min(195,(elapsed-60)*7):0}
function updatePlayer(p,dt){p.holster=Math.max(0,p.holster-dt);p.recoil=Math.max(0,p.recoil-dt*9);p.muzzle=Math.max(0,p.muzzle-dt);p.slash=Math.max(0,p.slash-dt);p.shot-=dt;p.dodge=Math.max(0,p.dodge-dt);p.inv-=dt;p.shield=Math.max(0,p.shield-dt);p.melee=Math.max(0,p.melee-dt);p.emptyNotice-=dt;const reloading=p.reload>0;p.reload=Math.max(0,p.reload-dt);if(reloading&&p.reload===0)finishReload(p);
 let dx=0,dy=0,shoot=false;if(p.id===1&&mode==='cpu'){({dx,dy,shoot}=aiInput(p,dt))}else if(p.id===0){dx=(keys.KeyD?1:0)-(keys.KeyA?1:0);dy=(keys.KeyS?1:0)-(keys.KeyW?1:0);p.angle=mode==='cpu'?Math.atan2(mouse.y-p.y,mouse.x-p.x):Math.atan2(players[1].y-p.y,players[1].x-p.x);shoot=mode==='cpu'?mouse.down:keys.KeyF;if(keys.Space)roll(p);if(keys.KeyV)melee(p)}else{dx=(keys.ArrowRight?1:0)-(keys.ArrowLeft?1:0);dy=(keys.ArrowDown?1:0)-(keys.ArrowUp?1:0);p.angle=Math.atan2(players[0].y-p.y,players[0].x-p.x);shoot=keys.KeyL;if(keys.ShiftRight||keys.ShiftLeft)roll(p);if(keys.KeyN)melee(p)}
 const len=Math.hypot(dx,dy);p.moving=!!len;if(len){dx/=len;dy/=len;p.walk+=dt*14;if(p.roll<=0){p.dx=dx;p.dy=dy}}if(p.roll>0){p.roll-=dt;move(p,p.dx*590,p.dy*590,dt);if(Math.random()<.35)burst(p.x,p.y,p.color,2)}else move(p,dx*characters[p.char].speed*(hasRelic(p,'feather')?1.12:1),dy*characters[p.char].speed*(hasRelic(p,'feather')?1.12:1),dt);if(shoot)fire(p);
 const inset=arenaInset();if(inset&&(p.x<inset+25||p.x>W-inset-25||p.y<inset*.58+25||p.y>H-inset*.58-25))damage(p,.16,true)}
function explode(b){const g=guns[b.gun],owner=players[b.owner];if(b.shard)return;if(b.parcel){weaponEffect(1,b.x,b.y);for(let i=0;i<5;i++)spawnBullet(owner,i*Math.PI*2/5,{gun:0,x:b.x,y:b.y,speed:240,damage:.35,life:.7,r:4,shard:true,canLens:false});pulse(b.x,b.y,g.color,55);combatSound('boom',b.gun)}if(g.split||g.comet||g.clover){const n=g.clover?4:g.comet?12:8;for(let i=0;i<n;i++)spawnBullet(owner,i*Math.PI*2/n,{gun:0,x:b.x,y:b.y,speed:g.comet?260:280,damage:g.clover?.65:g.comet?.45:.65,life:g.clover?.85:1.5,r:4,color:g.color,shard:true,shape:'star',canLens:false});burst(b.x,b.y,g.color,g.comet?32:20);pulse(b.x,b.y,g.color,g.comet?95:45);if(g.comet){const enemy=players[1-b.owner];if(dist(b,enemy)<82&&!lineBlocked(b,enemy))damage(enemy,1.5);shake=5}combatSound('boom',b.gun)}if(g.gravity){wells.push({x:b.x,y:b.y,owner:b.owner,life:2,tick:0,color:g.color});pulse(b.x,b.y,g.color,100);tone(100,.3,'sine')}}
function updateBullets(dt){const count=bullets.length;for(let i=0;i<count;i++){const b=bullets[i];if(b.dead)continue;const g=guns[b.gun],enemy=players[1-b.owner];b.life-=dt;b.age+=dt;
 if(g.seed&&b.age>=.6){b.vx=0;b.vy=0}
 if(g.boost){const v=Math.hypot(b.vx,b.vy),next=Math.min(760*b.speedScale,v+500*b.speedScale*dt);if(v){b.vx*=next/v;b.vy*=next/v}}
 if(g.bubble&&b.age>=1&&!b.launched){b.launched=true;const v=Math.hypot(b.vx,b.vy);if(v){b.vx*=480*b.speedScale/v;b.vy*=480*b.speedScale/v}pulse(b.x,b.y,b.color,20)}
 if(g.homing&&!b.shard){const a=Math.atan2(enemy.y-b.y,enemy.x-b.x),cur=Math.atan2(b.vy,b.vx),diff=Math.atan2(Math.sin(a-cur),Math.cos(a-cur)),na=cur+clamp(diff,-dt*(g.comet?.7:1.25),dt*(g.comet?.7:1.25));const speed=Math.hypot(b.vx,b.vy);b.vx=Math.cos(na)*speed;b.vy=Math.sin(na)*speed}
 if(g.boomerang&&b.age>.65){const p=players[b.owner],a=Math.atan2(p.y-b.y,p.x-b.x);b.vx+=(Math.cos(a)*470*b.speedScale-b.vx)*dt*4;b.vy+=(Math.sin(a)*470*b.speedScale-b.vy)*dt*4;if(dist(p,b)<20)b.life=0}
 // Substeps prevent fast rail shots from crossing thin collision edges.
 const steps=Math.max(1,Math.ceil(Math.hypot(b.vx,b.vy)*dt/7)),sub=dt/steps;
 for(let s=0;s<steps&&b.life>0;s++){const ox=b.x,oy=b.y;b.x+=b.vx*sub;b.y+=b.vy*sub;if(g.helix){b.x+=-b.vy/g.speed*Math.cos(b.age*14)*90*sub*b.phase;b.y+=b.vx/g.speed*Math.cos(b.age*14)*90*sub*b.phase}
 const wall=b.x<32||b.x>W-32||b.y<37||b.y>H-30,block=blocks.find(r=>circleRect(b.x,b.y,b.r,r));if((wall||block)&&!g.boomerang){if(b.bounce>0){b.bounce--;b.rebounds++;if(g.bank)weaponEffect(0,ox,oy,Math.atan2(-b.vy,-b.vx)+Math.PI/4);if(g.bank)b.damage+=.25;if(b.rebounds===1&&hasRelic(players[b.owner],'rebound')){b.vx*=1.2;b.vy*=1.2}if(block){if(ox<block.x||ox>block.x+block.w)b.vx*=-1;else b.vy*=-1}else{if(b.x<32||b.x>W-32)b.vx*=-1;if(b.y<37||b.y>H-30)b.vy*=-1}b.x=ox;b.y=oy;burst(b.x,b.y,b.color,4)}else{b.x=ox;b.y=oy;burst(b.x,b.y,b.color,7);if(g.switcher&&!b.shard)weaponEffect(2,b.x,b.y,Math.atan2(b.vy,b.vx)+Math.PI/4);b.life=0;break}}
 const key=b.age>.7?'back':'out';if(dist(b,enemy)<enemy.r+b.r&&(enemy.inv<=0||(b.volley!==null&&enemy.lastVolley===b.volley))&&(!g.boomerang||!b.hit.has(key))){damage(enemy,b.damage,false,b.volley);if(g.switcher&&!b.shard)weaponEffect(2,b.x,b.y,Math.atan2(b.vy,b.vx)+Math.PI/4);b.hit.add(key);if(!g.boomerang){b.life=0;break}}}
 if(b.life<=0){b.dead=true;explode(b)}}bullets=bullets.filter(b=>!b.dead);if(bullets.length>600)bullets.splice(0,bullets.length-600)}
function updateWells(dt){for(const w of wells){w.life-=dt;w.tick-=dt;const p=players[1-w.owner],d=dist(w,p);if(d<115&&p.roll<=0&&d>4)move(p,(w.x-p.x)/d*65,(w.y-p.y)/d*65,dt);if(w.tick<=0){w.tick=.45;if(d<43&&!lineBlocked(w,p))damage(p,.4)}for(const b of bullets){if(b.owner===w.owner)continue;const n=dist(w,b);if(n<125){if(n<15)b.dead=true;else{b.vx+=(w.x-b.x)/n*550*dt;b.vy+=(w.y-b.y)/n*550*dt}}}}wells=wells.filter(w=>w.life>0);bullets=bullets.filter(b=>!b.dead)}
function update(dt){if(state==='paused'||$('book').open)return;weaponEffects.forEach(e=>e.age+=dt);weaponEffects=weaponEffects.filter(e=>e.age<e.duration);toastTime-=dt;if(toastTime<=0)$('toast').style.opacity=0;particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt});particles=particles.filter(p=>p.life>0);rings.forEach(r=>{r.r+=r.speed*dt;r.life-=dt});rings=rings.filter(r=>r.life>0);shake=Math.max(0,shake-30*dt);if(state!=='play')return;
 time=Math.max(0,time-dt);elapsed+=dt;supplyTimer-=dt;relicTimer-=dt;if(supplyTimer<=0){supplyTimer=14;spawnSupply()}if(relicTimer<=0){relicTimer=18;spawnRelics()}if(elapsed>=25&&!legendaryWarned){legendaryWarned=true;toast('あと5秒！ 中央の上下にSレア武器が投下')}if(elapsed>=30&&!legendarySpawned){legendarySpawned=true;const pool=guns.map((g,i)=>g.rarity==='S'?i:-1).filter(i=>i>=0),g=pool[Math.floor(Math.random()*pool.length)];for(const s of [{x:560,y:205},{x:560,y:395}])putItem({...s,kind:'weapon',gun:g});toast('S LEGENDARY 到着！ 中央にSランク武器を2丁投下');tone(850,.3)}
 for(const p of players)updatePlayer(p,dt);for(const shot of delayedShots){shot.delay-=dt;if(shot.delay<=0&&players[shot.owner].hp>0){const p=players[shot.owner];spawnBullet(p,shot.angle,{gun:shot.gun,damage:shot.damage,volley:shot.volley});weaponEffect(3,p.x+Math.cos(shot.angle)*34,p.y+Math.sin(shot.angle)*34,shot.angle)}}delayedShots=delayedShots.filter(s=>s.delay>0);for(const item of pickups){item.age+=dt;if(item.used)continue;for(const p of players){if(!item.used&&dist(item,p)<31)acquire(p,item)}}pickups=pickups.filter(i=>!i.used&&i.age<42);updateBullets(dt);updateWells(dt);if(players.some(p=>p.hp<=0)||time<=0)endRound();hudTick+=dt;if(hudTick>.1){hudTick=0;updateHUD()}}
function endRound(){const a=players[0].hp/players[0].maxHp,b=players[1].hp/players[1].maxHp,winner=Math.abs(a-b)<.001?-1:a>b?0:1;if(winner>=0)scores[winner]++;state='result';delayedShots=[];const done=scores.some(n=>n>=3);overlay(`<div class="startpanel"><div class="eyebrow">${done?'MATCH COMPLETE':'ROUND '+roundNo+' COMPLETE'}</div>${winner>=0?`<span class="portrait resultportrait c${players[winner].char}"></span>`:''}<h2>${winner<0?'DRAW':`P${winner+1} <em>WINS!</em>`}</h2><p>${winner>=0?characters[players[winner].char].name+' の勝利！':'引き分け！'}　${scores[0]} — ${scores[1]}<br>${done?'再戦する？':'次は装備をリセットし、ショップで作戦変更。'}</p><div class="menuactions"><button class="primary" id="continue">${done?'もう一度対戦':'次のラウンド'} ✦</button>${done?'<button id="changehero" class="textbutton">ファイターを変える</button>':''}</div></div>`);$('continue').onclick=done?startMatch:nextRound;if(done)$('changehero').onclick=showCharacters;tone(winner===0?650:280,.3);updateHUD()}
function inventoryHTML(p,id){return Array.from({length:4},(_,i)=>{const w=p?.inventory[i];if(!w)return `<button class="slot empty" disabled>空き ${i+1}</button>`;const g=guns[w.id],r=RARITIES[g.rarity];return `<button class="slot ${p.active===i?'selected':''}" style="--rarity:${r.color}" data-slot="${i}" data-player="${id}" ${id===1&&mode==='cpu'?'disabled':''} aria-label="${g.name}、装填${w.clip}、予備${w.reserve}" aria-pressed="${p.active===i}"><span class="slothead"><span>${i+1}　${g.glyph}</span><span>${g.rarity}</span></span>${weaponArt(w.id)}<b>${g.name}</b><span class="ammonum">${p.reload&&p.active===i?'装填中…':w.clip+' / '+w.reserve+(g.switcher?(w.mode?' 散弾':' 単発'):'')}</span></button>`}).join('')}
function updateHUD(){for(let i=0;i<2;i++){const p=players[i],hp=p?.hp??8,max=p?.maxHp??8;$('hp'+(i+1)).innerHTML=`<span class="hpsegments">${Array.from({length:max},(_,j)=>`<i style="opacity:${clamp(hp-j,0,1)*.8+.2}"></i>`).join('')}</span><span class="hpvalue">${hp.toFixed(1)} / ${max}</span>`;$('hp'+(i+1)).title=`HP ${hp.toFixed(1)} / ${max}`;$('score'+(i+1)).textContent=scores[i];const name=characters[p?.char??selectedChars[i]].name;$(i?'enemylabel':'name1').textContent=name+(i&&mode==='cpu'?' / CPU':'');const inv=$('inventory'+(i+1)),html=inventoryHTML(p,i);if(inv.innerHTML!==html){inv.innerHTML=html;inv.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{if(state==='play')equipSlot(players[+b.dataset.player],+b.dataset.slot)})}$('abilities'+(i+1)).textContent=p?`回避 ${p.dodge>0?p.dodge.toFixed(1)+'s':'OK'} · 近接 ${p.melee>0?p.melee.toFixed(1)+'s':'OK'} · パルス ${p.blanks}`:'回避 OK · パルス 2';$('relics'+(i+1)).innerHTML=p?.relics.length?p.relics.map(n=>`<span class="relicchip" style="color:${relics[n].color}" title="${relics[n].desc}">${relics[n].glyph} ${relics[n].name}${relics[n].key==='bell'&&p.shield>0?' '+Math.ceil(p.shield)+'s':''}</span>`).join(''):`レリック 0 / 3　<span>拾って組み合わせよう</span>`}
 $('clock').textContent=Math.ceil(time);$('round').textContent=roundNo?'ROUND '+roundNo+' · 3本先取':'3本先取';}
function pause(){if(state==='play'){state='paused';overlay('<div class="startpanel"><div class="eyebrow">MATCH PAUSED</div><h2><em>PAUSE</em></h2><p>Esc で対戦に戻る</p><button class="primary" id="resume">対戦に戻る</button><p><button class="textbutton" id="restart">対戦を最初から</button> <button class="textbutton" id="backmenu">ファイターを選び直す</button></p></div>');$('resume').onclick=pause;$('restart').onclick=startMatch;$('backmenu').onclick=showCharacters}else if(state==='paused'){state='play';hideOverlay()}}
function controls(){ $('controls').innerHTML=mode==='cpu'?'<kbd>WASD</kbd> 移動 ／ マウス 照準・クリック射撃 ／ <kbd>Space</kbd> 回避 ／ <kbd>Q</kbd> 弾消し':'P1：WASD 移動・F 射撃・Space 回避・Q 弾消し ｜ P2：矢印 移動・L 射撃・Shift 回避・O 弾消し';$('extraControls').textContent=mode==='cpu'?'E / ホイール / 1〜4 武器切替 · R リロード · V 近接 · Esc 一時停止 · 弾数表示：装填 / 予備':'双方オート照準 ｜ P1：E / 1〜4 切替・R 装填・V 近接 ｜ P2：K 切替・P 装填・N 近接 ｜ Esc 一時停止';}
function setMode(m){if(m===mode)return;if(['play','paused','draft','result','shop'].includes(state)&&!confirm('現在の対戦を終了して、モードを切り替えますか？'))return;mode=m;$('cpu').classList.toggle('active',m==='cpu');$('local').classList.toggle('active',m==='local');controls();showMenu();showCharacters()}
$('cpu').onclick=()=>setMode('cpu');$('local').onclick=()=>setMode('local');$('pause').onclick=pause;$('sound').onclick=()=>{sound=!sound;$('sound').textContent='♪ 音 '+(sound?'ON':'OFF');tone(500)};
$('raritylegend').innerHTML=Object.entries(RARITIES).map(([k,r])=>`<span style="color:${r.color}">${k} ${r.label}</span>`).join('');$('weaponlist').innerHTML=guns.map((g,i)=>`<article class="weaponcard" style="--rarity:${RARITIES[g.rarity].color}">${gunCard(i)}</article>`).join('');$('reliclist').innerHTML=relics.map(r=>`<article class="weaponcard" style="--rarity:${r.color}"><div class="glyph">${r.glyph}</div><h3>${r.name}</h3><p>${r.desc}</p></article>`).join('');
$('armory').onclick=()=>{bookPaused=state==='play';if(bookPaused)pause();clearInput();$('book').showModal()};$('closebook').onclick=()=>$('book').close();$('book').addEventListener('close',()=>{if(bookPaused&&state==='paused')pause();bookPaused=false;clearInput()});
window.addEventListener('keydown',e=>{if($('book').open)return;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Escape'){pause();return}keys[e.code]=true;if(e.repeat||state!=='play')return;const p=players[0],q=players[1];if(e.code==='KeyQ')blank(p);if(e.code==='KeyE')switchGun(p);if(e.code==='KeyR')reload(p);if(e.code==='KeyG')interact(p);if(/^Digit[1-4]$/.test(e.code))equipSlot(p,+e.code.slice(-1)-1);if(mode==='local'){if(e.code==='KeyO')blank(q);if(e.code==='KeyK')switchGun(q);if(e.code==='KeyP')reload(q);if(e.code==='KeyH')interact(q)}});
window.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>{clearInput();if(state==='play')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='play')pause()});
cv.addEventListener('pointermove',e=>{const r=cv.getBoundingClientRect(),scale=Math.min(r.width/W,r.height/H);mouse.x=(e.clientX-r.left-(r.width-W*scale)/2)/scale;mouse.y=(e.clientY-r.top-(r.height-H*scale)/2)/scale});cv.addEventListener('pointerdown',e=>{if(e.button===0&&state==='play')mouse.down=true});window.addEventListener('pointerup',()=>mouse.down=false);cv.addEventListener('contextmenu',e=>e.preventDefault());cv.addEventListener('wheel',e=>{if(state==='play'){e.preventDefault();switchGun(players[0],e.deltaY>0?1:-1)}},{passive:false});
controls();showMenu();
